SELECT id,target_kind,device_id,application_id,instance_id,node_id,owner_user,owner_guest,login_session_id,owner_revision,client_type,access_role,request_hash,state,revision,node_generation,control_epoch,endpoint_revision,created_at,closed_at FROM pixels.resource_sessions WHERE ($1::uuid IS NULL OR id>$1) ORDER BY id LIMIT $2
